import { TransitionSeries, linearTiming } from '@remotion/transitions';
import { wipe } from '@remotion/transitions/wipe';
import { Easing, spring, useCurrentFrame, useVideoConfig } from 'remotion';

export const WipeIn = (props: { children?: React.ReactNode }) => {
	return (
		<TransitionSeries>
			<TransitionSeries.Transition
				timing={linearTiming({
					durationInFrames: 40,
					easing: Easing.inOut(Easing.ease),
				})}
				presentation={wipe({ direction: 'from-left' })}
			/>
			<TransitionSeries.Sequence durationInFrames={2000}>
				{props.children}
			</TransitionSeries.Sequence>
		</TransitionSeries>
	);
};

export const WipeInAndOut = (props: {
	children?: React.ReactNode;
	durationInFrames: number;
}) => {
	return (
		<TransitionSeries>
			<TransitionSeries.Transition
				timing={linearTiming({
					durationInFrames: 40,
					easing: Easing.inOut(Easing.ease),
				})}
				presentation={wipe({ direction: 'from-left' })}
			/>
			<TransitionSeries.Sequence durationInFrames={props.durationInFrames + 20}>
				{props.children}
			</TransitionSeries.Sequence>
			<TransitionSeries.Transition
				timing={linearTiming({
					durationInFrames: 40,
					easing: Easing.inOut(Easing.ease),
				})}
				presentation={wipe({ direction: 'from-left' })}
			/>
		</TransitionSeries>
	);
};

export const createSlideTimings = <T extends Record<string, number>>(
	config: T
) => {
	let total = 0;

	const slides = Object.entries(config).reduce(
		(acc, [key, value]) => {
			(acc as any)[key] = {
				duration: value,
				from: total,
				to: total + value,
			};

			total += value;

			return acc;
		},
		{} as Record<
			keyof T,
			{
				duration: number;
				from: number;
				to: number;
			}
		>
	);

	return {
		slides,
		durationInFrames: total,
	};
};

